  local function word(n) return string.char(rs(n,24)%256,rs(n,16)%256,rs(n,8)%256,n%256) end
  local length=#input
  local data=input..'\128'..string.rep('\0',(55-length)%64)..word(math.floor(length/536870912))..word((length*8)%4294967296)
  local h={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19}
