      local t2=(bx(rr(a,2),rr(a,13),rr(a,22))+bx(band(a,b),band(a,c),band(b,c)))%4294967296
      z,g,f,e,d,c,b,a=g,f,e,(d+t1)%4294967296,c,b,a,(t1+t2)%4294967296
