modules["autobuilder.install.cli"]=function()
local Manager=require('autobuilder.install.manager')
local M={}
function M.run(args,e,base,recovery)
  if args[1]=='fleet' then local rest={};for i=2,#args do rest[#rest+1]=args[i] end;return require('autobuilder.install.fleet').run(rest,e,base,recovery) end
  local opts={defaultBase=base,recoverySource=recovery}; local i=1
  while i<=#args do
    local arg=args[i]
    if arg=='--base' or arg=='--controller' then
      assert(args[i+1],'Missing value for '..arg)
      opts[arg=='--base' and 'base' or 'controllerId']=args[i+1]; i=i+1
    elseif arg=='--recover' then opts.recover=true
    elseif arg=='--reboot' then opts.reboot=true
    elseif arg=='update' and not opts.role and not opts.mode then opts.mode='update'
    elseif arg=='--help' or arg=='help' then
      e.print('installer <controller|worker|miner|builder|logger|courier> [controllerID] [--base URL] [--reboot]')
      e.print('update [--base URL] [--reboot] | installer --recover'); return true
    elseif not arg:match('^%-') and not opts.role and not opts.mode then opts.role=arg
    elseif opts.role and not opts.controllerId and arg:match('^%d+$') then opts.controllerId=arg
    else error('Unknown argument: '..arg,0) end
    i=i+1
  end
  local result=Manager.run(e,opts)
  if opts.reboot then e.os.reboot() end
  return result
end
return M

end
modules["autobuilder.core.util"]=function()
local M = {}
function M.finite(n) return type(n)=='number' and n==n and n~=math.huge and n~=-math.huge end
function M.shortString(s,limit)
  return type(s)=='string' and #s>0 and #s<=(limit or 64) and not s:find('[%c]')
end
function M.integer(n) return M.finite(n) and n%1==0 end
function M.position(p)
  return type(p)=='table' and M.integer(p.x) and M.integer(p.y) and M.integer(p.z)
    and math.abs(p.x)<=30000000 and math.abs(p.z)<=30000000 and math.abs(p.y)<=30000000
end
function M.copy(v)
  if type(v)~='table' then return v end
  local out={}; for k,x in pairs(v) do out[k]=M.copy(x) end; return out
end
function M.distance(a,b) return math.abs(a.x-b.x)+math.abs(a.y-b.y)+math.abs(a.z-b.z) end
function M.heading(h) return h=='north' or h=='east' or h=='south' or h=='west' end
return M

end
modules["autobuilder.core.checkpoint"]=function()
local M={}
-- Adler-32 uses exact integer arithmetic even on Lua's double-number runtime.
local function checksum(s)
  local a,b=1,0
  -- Batch reductions without yielding inside a transaction. Even the largest
  -- intermediate sum stays below 2^32, exactly representable by Lua doubles.
  for start=1,#s,4096 do
    for i=start,math.min(start+4095,#s) do a=a+s:byte(i);b=b+a end
    a=a%65521;b=b%65521
  end
  return b*65536+a
end
function M.new(fs,codec,path)
  assert(type(path)=='string' and #path>0,'checkpoint path required')
  local self={}
  local function read(p)
    if not fs.exists(p) then return nil,'missing' end
    local ok,result=pcall(function()
      local h,err=fs.open(p,'r'); assert(h,err)
      local raw=h.readAll(); h.close()
      local e=codec.unserialize(raw)
      assert(type(e)=='table' and e.version==1 and type(e.payload)=='string','invalid envelope')
      assert(e.checksum==checksum(e.payload),'checksum mismatch')
      local value=codec.unserialize(e.payload); assert(type(value)=='table','invalid payload')
      return value
    end)
    if ok then return result end
    return nil,tostring(result)
  end
  function self:load()
    local value,err=read(path); if value then return value,'primary' end
    local backup,berr=read(path..'.bak'); if backup then return backup,'backup (primary: '..err..')' end
    if err=='missing' and berr=='missing' and not fs.exists(path..'.tmp') then return nil,'missing' end
    return nil,'No valid checkpoint: '..err..'; backup: '..berr..'. Preserve files and investigate.'
  end
  function self:save(value)
    local ok,err=pcall(function()
      assert(type(value)=='table','checkpoint must be a table')
      local dir=fs.getDir(path); if dir~='' then fs.makeDir(dir) end
      local payload=codec.serialize(value,{compact=true})
      local raw=codec.serialize({version=1,payload=payload,checksum=checksum(payload)},{compact=true})
      local h,why=fs.open(path..'.tmp','w'); assert(h,why)
      h.write(raw); h.close()
      assert(read(path..'.tmp'),'temporary checkpoint did not validate')
      -- Do not replace a good backup with a damaged primary during recovery.
      if read(path) then
        if fs.exists(path..'.bak') then fs.delete(path..'.bak') end
        fs.move(path,path..'.bak')
      elseif fs.exists(path) then fs.delete(path) end
      fs.move(path..'.tmp',path)
    end)
    if not ok then return false,'checkpoint save failed: '..tostring(err) end
    return true
  end
  return self
end
return M

end
modules["autobuilder.core.setup_state"]=function()
local U=require('autobuilder.core.util')
local Checkpoint=require('autobuilder.core.checkpoint')
local M={}
function M.idle(e,config,preparation)
  local store=Checkpoint.new(e.fs,e.textutils,config.dataDir..'/'..config.role..'.state')
  local state,source=store:load()
  assert(source=='primary' or source=='missing','Checkpoint recovery required before setup: '..source)
  if state then
    assert(state.schema==1 and state.id==e.os.getComputerID() and state.role==config.role
      and U.integer(state.boot) and type(state.phase)=='string','Invalid or foreign checkpoint')
    assert(not state.inventoryRecovery,'Quarantined inventory recovery owner cannot change setup')
    assert(not state.fuelRecovery and not state.fuelResume,'Finish fuel recovery before setup')
    assert(not state.assignmentRecovery and not state.currentTask and not state.motionReservation
      and not next(state.pendingSupplyAcks or {}),'Finish current jobs and acknowledgements before setup')
    assert(not (state.firstBuild and state.firstBuild.autoStart),'Finish the requested first test before changing setup; pausing keeps its saved settings in use')
    if config.role=='worker' then
      assert(type(state.position)=='table' and type(state.position.known)=='boolean','Invalid saved position')
      assert(not state.position.pending and not state.position.uncertain,'Recover uncertain movement with /autobuilder/pose.lua before setup')
    end
    local a=state.automation or {}
    for _,r in pairs(a.inventoryRecoveries or {}) do assert(r.status=='completed','Finish inventory recovery before setup') end
    assert(not a.supply,'Finish the outstanding supply batch before setup')
    for _,jobs in ipairs({state.jobs or {},a.jobs or {},preparation and {} or a.requests or {}}) do
      for _,job in pairs(jobs) do
        assert(job.type~='RESCUE' or job.rescueSettled,'Finish fuel recovery before setup')
        assert(job.status=='completed','Finish queued or paused work before setup')
      end
    end
    for _,project in pairs(a.projects or {}) do
      assert(not ({building=true,verifying=true,repairing=true,clearing=true,preparing=not preparation})[project.phase],
        'Finish the active project before setup')
    end
  end
  return store,state
end
return M

end
